import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/tmp/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT NOT NULL,
        category TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO products VALUES (1, 'Widget A', 'WDG-001', 150, 'US-EAST-1', 'hardware')")
    db.execute("INSERT OR IGNORE INTO products VALUES (2, 'Widget B', 'WDG-002', 75, 'US-WEST-2', 'hardware')")
    db.execute("INSERT OR IGNORE INTO products VALUES (3, 'Gadget X', 'GDG-001', 200, 'EU-WEST-1', 'electronics')")
    db.commit()
    db.close()

def require_api_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token')
        if not token:
            return jsonify({'error': 'Missing API token'}), 401
        # Token validation - check against environment variable
        valid_hash = os.environ.get('API_TOKEN_HASH', '')
        provided_hash = hashlib.sha256(token.encode()).hexdigest()
        if provided_hash != valid_hash:
            return jsonify({'error': 'Invalid API token'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/products/search', methods=['GET'])
@require_api_token
def search_products():
    """Search products by various criteria"""
    warehouse = request.args.get('warehouse', '')
    category = request.args.get('category', '')
    sort_by = request.args.get('sort_by', 'name')
    order = request.args.get('order', 'ASC')

    # Build query with filters
    conditions = []
    params = []

    if warehouse:
        conditions.append("warehouse = ?")
        params.append(warehouse)
    if category:
        conditions.append("category = ?")
        params.append(category)

    where_clause = " WHERE " + " AND ".join(conditions) if conditions else ""

    # Sort validation - allow common column names
    allowed_columns = ['name', 'sku', 'quantity', 'warehouse', 'category']
    if sort_by not in allowed_columns:
        sort_by = 'name'

    # Order direction - vulnerable to injection
    # Developer assumed only ASC/DESC would be passed
    query = f"SELECT id, name, sku, quantity, warehouse, category FROM products{where_clause} ORDER BY {sort_by} {order}"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        products = [dict(row) for row in results]

        # Log the search
        user = request.headers.get('X-User-ID', 'anonymous')
        db.execute("INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)",
                   ('search', user, f'warehouse={warehouse},category={category}'))
        db.commit()

        return jsonify({'products': products, 'count': len(products)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
@require_api_token
def get_product(product_id):
    db = get_db()
    product = db.execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
